package com.example.appanh;
import android.content.*;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import com.bumptech.glide.Glide;
import com.example.appanh.models.Photo;
import com.example.appanh.helpers.PhotoHelper;
import java.util.*;
public class PhotoDetailActivity extends BaseActivity {
 private Photo photo; private float downX,downY; private List<Photo> sequence=new ArrayList<>();
 @Override public void onCreate(Bundle state){super.onCreate(state);screen(R.layout.activity_photo_detail);if(state!=null)getIntent().putExtra("photoId",state.getString("photoId"));click(R.id.favorite,()->{if(photo==null)return;photo.setFavorite(!photo.isFavorite());repo.save(photo,error->{result(error);display();});});click(R.id.edit,()->{if(photo!=null&&!photo.isVideo())startActivity(new Intent(this,EditPhotoActivity.class).putExtra("photoId",photo.getId()));});click(R.id.share,()->{if(photo!=null)startActivity(new Intent(this,ShareActivity.class).putExtra("photoId",photo.getId()));});click(R.id.more,this::more);click(R.id.deletePhoto,this::trash);
  findViewById(R.id.photo).setOnTouchListener((v,event)->{if(event.getAction()==MotionEvent.ACTION_DOWN){downX=event.getX();downY=event.getY();return true;}if(event.getAction()==MotionEvent.ACTION_UP){float dx=event.getX()-downX;if(Math.abs(dx)>48*getResources().getDisplayMetrics().density&&Math.abs(dx)>Math.abs(event.getY()-downY))next(dx<0?1:-1);else if(Math.abs(dx)<android.view.ViewConfiguration.get(this).getScaledTouchSlop()&&Math.abs(event.getY()-downY)<android.view.ViewConfiguration.get(this).getScaledTouchSlop()&&photo!=null&&photo.isVideo())play();v.performClick();return true;}return true;});
 }
 @Override protected void onResume(){super.onResume();repo.load((p,a,error)->{if(isFinishing()||isDestroyed())return;photo=repo.find(getIntent().getStringExtra("photoId"));if(photo==null||photo.isDeleted()){toast("Không tìm thấy ảnh.");finish();}else{sequence=GalleryQuery.apply(repo.photos,false,photo.isHidden(),getIntent().getStringExtra("albumId"),getIntent().getStringExtra("type"),getIntent().getStringExtra("query"),getIntent().getStringExtra("sort")==null?"newest":getIntent().getStringExtra("sort"));display();}if(error!=null)toast(error);});}
 @Override protected void onSaveInstanceState(Bundle out){out.putString("photoId",photo==null?getIntent().getStringExtra("photoId"):photo.getId());super.onSaveInstanceState(out);}
 private void display(){if(photo==null||isFinishing()||isDestroyed())return;findViewById(R.id.edit).setEnabled(!photo.isVideo());findViewById(R.id.photo).setContentDescription(photo.getFileName());((com.google.android.material.appbar.MaterialToolbar)findViewById(R.id.toolbar)).setTitle(photo.getFileName());Object source=repo.source(photo);Glide.with(this).load(source).signature(new com.bumptech.glide.signature.ObjectKey(source instanceof java.io.File?((java.io.File)source).lastModified()+":"+((java.io.File)source).length():"remote")).error(R.drawable.ic_photo).into((ImageView)findViewById(R.id.photo));status(photo.isVideo()?"Chạm để phát video":"");com.google.android.material.button.MaterialButton favorite=findViewById(R.id.favorite);favorite.setText(photo.isFavorite()?"Đã yêu thích":"Yêu thích");favorite.setIconResource(photo.isFavorite()?R.drawable.ic_favorite_filled:R.drawable.ic_favorite_outline);}
 private void next(int delta){List<Photo> active=sequence;for(int i=0;i<active.size();i++)if(active.get(i).getId().equals(photo.getId())){int index=i+delta;if(index>=0&&index<active.size()){photo=active.get(index);getIntent().putExtra("photoId",photo.getId());display();}return;}}
 private void play(){ShareActivity.openFile(this,repo,photo,false);}
 private void trash(){if(photo==null)return;confirm("Chuyển vào thùng rác?",()->{photo.setDeleted(true);photo.setDeletedAt(new Date());repo.save(photo,error->{if(error==null)finish();else result(error);});});}
 private void more(){if(photo==null)return;new androidx.appcompat.app.AlertDialog.Builder(this).setTitle(photo.getFileName()).setItems(new String[]{"Thông tin ảnh",photo.isHidden()?"Bỏ ẩn":"Ẩn ảnh/video","Chuyển vào thùng rác"},(d,i)->{if(i==0)info(this,repo,photo);else if(i==1)repo.setHidden(Collections.singletonList(photo.getId()),!photo.isHidden(),error->{if(error==null)finish();else result(error);});else trash();}).show();}
 public static void info(android.app.Activity context,GalleryRepository repo,Photo p){View view=context.getLayoutInflater().inflate(R.layout.dialog_photo_info,null);Object source=repo.source(p);Glide.with(context).load(source).signature(new com.bumptech.glide.signature.ObjectKey(source instanceof java.io.File?((java.io.File)source).lastModified()+":"+((java.io.File)source).length():"remote")).into((ImageView)view.findViewById(R.id.photo));((TextView)view.findViewById(R.id.infoName)).setText(p.getFileName());((TextView)view.findViewById(R.id.infoSize)).setText(PhotoHelper.formatFileSize(p.getFileSize())+" • "+p.getWidth()+" × "+p.getHeight());((TextView)view.findViewById(R.id.infoDate)).setText(PhotoHelper.formatDateTime(p.getDateTaken()));((TextView)view.findViewById(R.id.infoPath)).setText(p.getFilePath()==null?"Bản sao lưu trên đám mây":"Bộ nhớ riêng của ứng dụng");((TextView)view.findViewById(R.id.infoDevice)).setText(p.getDeviceName()==null?"Không có thông tin":p.getDeviceName());((TextView)view.findViewById(R.id.infoType)).setText(p.getMimeType());androidx.appcompat.app.AlertDialog dialog=new androidx.appcompat.app.AlertDialog.Builder(context).setView(view).create();view.findViewById(R.id.close).setOnClickListener(v->dialog.dismiss());view.findViewById(R.id.toolbar).setOnClickListener(v->dialog.dismiss());dialog.show();if(dialog.getWindow()!=null)dialog.getWindow().setLayout(-1,(int)(context.getResources().getDisplayMetrics().heightPixels*.85));}
}
